#include <BLEDevice.h>
#include <BLEUtils.h>
#include <BLEBeacon.h>
#include <BLEAdvertising.h>
#include <BLEServer.h>
#include <BLE2902.h>

// ===== RGB LED =====
// Обычный катодный (минус общий) LED. Если у тебя с общим анодом —
// замени analogWrite(pin, x) на analogWrite(pin, 255 - x)
#define PIN_R 4
#define PIN_G 5
#define PIN_B 6

// ===== Nordic UART Service — его понимают все BLE-терминалы =====
#define SERVICE_UUID           "6E400001-B5A3-F393-E0A9-E50E24DCCA9E"
#define CHARACTERISTIC_UUID_RX "6E400002-B5A3-F393-E0A9-E50E24DCCA9E" // телефон -> ESP32
#define CHARACTERISTIC_UUID_TX "6E400003-B5A3-F393-E0A9-E50E24DCCA9E" // ESP32 -> телефон

BLEServer* pServer = nullptr;
BLECharacteristic* pTxCharacteristic = nullptr;
bool deviceConnected = false;

std::string rxBuf = "";

void setColor(int r, int g, int b) {
  analogWrite(PIN_R, r);
  analogWrite(PIN_G, g);
  analogWrite(PIN_B, b);
}

void sendToPhone(const std::string& msg) {
  if (deviceConnected) {
    pTxCharacteristic->setValue(msg);
    pTxCharacteristic->notify();
  }
}

void handleCommand(const std::string& line) {
  int r = -1, g = -1, b = -1;
  if (sscanf(line.c_str(), "R: %d G: %d B: %d", &r, &g, &b) == 3) {
    if (r >= 0 && r <= 255 && g >= 0 && g <= 255 && b >= 0 && b <= 255) {
      setColor(r, g, b);
      char reply[48];
      snprintf(reply, sizeof(reply), "OK: R:%d G:%d B:%d\n", r, g, b);
      sendToPhone(reply);
      Serial.printf("[LED] R:%d G:%d B:%d\n", r, g, b);
      return;
    }
  }
  sendToPhone("Ошибка. Формат: R: 0-255 G: 0-255 B: 0-255\n");
  Serial.println("[BT] Не понял команду: " + line);
}

class ServerCallbacks : public BLEServerCallbacks {
  void onConnect(BLEServer* s) override {
    deviceConnected = true;
    Serial.println("[BT] Клиент подключился");
  }
  void onDisconnect(BLEServer* s) override {
    deviceConnected = false;
    Serial.println("[BT] Отключился, снова рекламируюсь...");
    s->getAdvertising()->start();
  }
};

class RxCallbacks : public BLECharacteristicCallbacks {
  void onWrite(BLECharacteristic* c) override {
    rxBuf += c->getValue();
    size_t pos;
    while ((pos = rxBuf.find('\n')) != std::string::npos) {
      std::string line = rxBuf.substr(0, pos);
      rxBuf.erase(0, pos + 1);
      if (!line.empty()) handleCommand(line);
    }
  }
};

void setup() {
  Serial.begin(115200);
  pinMode(PIN_R, OUTPUT);
  pinMode(PIN_G, OUTPUT);
  pinMode(PIN_B, OUTPUT);
  setColor(0, 0, 0);

  BLEDevice::init("ESP32 RGB Beacon");

  pServer = BLEDevice::createServer();
  pServer->setCallbacks(new ServerCallbacks());

  BLEService* pService = pServer->createService(SERVICE_UUID);

  pTxCharacteristic = pService->createCharacteristic(
      CHARACTERISTIC_UUID_TX,
      BLECharacteristic::PROPERTY_NOTIFY);
  pTxCharacteristic->addDescriptor(new BLE2902());

  BLECharacteristic* pRxCharacteristic = pService->createCharacteristic(
      CHARACTERISTIC_UUID_RX,
      BLECharacteristic::PROPERTY_WRITE | BLECharacteristic::PROPERTY_WRITE_NR);
  pRxCharacteristic->setCallbacks(new RxCallbacks());

  pService->start();

  // --- Твой маячок как раньше, плюс наш сервис в рекламе ---
  BLEBeacon beacon;
  beacon.setManufacturerId(0x4C00);
  beacon.setProximityUUID(BLEUUID("12345678-1234-1234-1234-123456789abc"));
  beacon.setMajor(1);
  beacon.setMinor(1);
  beacon.setSignalPower(-59);

  BLEAdvertisementData data;
  data.setFlags(0x06);              // 0x04 | 0x02: маячок + обычное discoverable-подключение
  data.setManufacturerData(beacon.getData());
  data.setCompleteServices(BLEUUID(SERVICE_UUID)); // чтобы приложение увидело UART-сервис

  BLEAdvertising* advertising = BLEDevice::getAdvertising();
  advertising->setAdvertisementData(data);
  advertising->start();

  Serial.println("BLE маячок + RGB-управление запущены");
}

void loop() {
  delay(1000);
}
